// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceMnemoEmbedder {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceMnemoEmbedder = UniffiVTableCallbackInterfaceMnemoEmbedder(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeMnemoEmbedder.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface MnemoEmbedder: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeMnemoEmbedder.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface MnemoEmbedder: handle missing in uniffiClone")
            }
        },
        identity: { (
            uniffiHandle: UInt64,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> EmbedderIdentity in
                guard let uniffiObj = try? FfiConverterTypeMnemoEmbedder.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.identity(
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterTypeEmbedderIdentity_lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        embed: { (
            uniffiHandle: UInt64,
            texts: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> [[Float]] in
                guard let uniffiObj = try? FfiConverterTypeMnemoEmbedder.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.embed(
                     texts: try FfiConverterSequenceString.lift(texts)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterSequenceSequenceFloat.lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeEmbedderError_lower
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceMnemoEmbedder> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceMnemoEmbedder>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitMnemoEmbedder() {
    uniffi_mnemo_uniffi_fn_init_callback_vtable_mnemoembedder(UniffiCallbackInterfaceMnemoEmbedder.vtablePtr)
}

