    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MnemoEmbedder {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: MnemoEmbedder, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


